fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // We only consider up to `n` participants.
    let limit = n as usize;
    let mut eligible_count: usize = 0;

    // Count how many participants can attend at least `k` more sessions.
    for &attended in participations.iter().take(limit) {
        // `5 - attended` is how many sessions they can still attend.
        // We use saturating_sub to avoid underflow, though by assumption
        // `attended <= 5` so it's safe either way.
        if 5u8.saturating_sub(attended) >= k {
            eligible_count += 1;
        }
    }

    // Each team requires exactly 3 eligible participants.
    // The maximum number of disjoint teams is eligible_count / 3.
    (eligible_count / 3) as u8
}